const serverUrl = $('Setup Form').item.json.serverUrl;
const orgName = $('Setup Form').item.json.organizationName;

// Create comprehensive integration tools using the existing Integration Service
const tools = [
  {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Searching for healthcare providers..."
      },
      {
        "type": "request-complete", 
        "content": "Found healthcare providers in your area."
      }
    ],
    "type": "function",
    "function": {
      "name": "search_healthcare_providers",
      "description": "Search for healthcare providers including doctors, hospitals, clinics, and pharmacies in the Greater Accra region. Use this when users need to find medical services.",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query describing the type of healthcare provider or service needed"
          },
          "location": {
            "type": "string", 
            "description": "Specific location or area within Greater Accra region"
          },
          "specialty": {
            "type": "string",
            "description": "Medical specialty if looking for a specialist doctor"
          },
          "provider_type": {
            "type": "string",
            "enum": ["doctor", "hospital", "clinic", "pharmacy", "emergency"],
            "description": "Type of healthcare provider"
          },
          "max_results": {
            "type": "integer",
            "default": 5,
            "description": "Maximum number of results to return"
          }
        },
        "required": ["query", "location"]
      }
    },
    "server": {
      "timeout": 20,
      "url": `${serverUrl}/premier-health/vapi-webhook`,
      "method": "POST"
    }
  },
  {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Sending email notification..."
      },
      {
        "type": "request-complete",
        "content": "Email sent successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "send_email_notification",
      "description": "Send healthcare provider information or appointment details via email using the Integration Service Resend integration.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "resend_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "send_email",
            "description": "Action to execute"
          },
          "recipient_email": {
            "type": "string",
            "description": "Email address to send information to"
          },
          "subject": {
            "type": "string",
            "description": "Email subject line"
          },
          "content": {
            "type": "string",
            "description": "Email content with healthcare provider details"
          },
          "sender_name": {
            "type": "string",
            "default": orgName,
            "description": "Sender name"
          }
        },
        "required": ["recipient_email", "subject", "content"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },
  {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Searching for current health information..."
      },
      {
        "type": "request-complete",
        "content": "Found relevant health information."
      }
    ],
    "type": "function",
    "function": {
      "name": "search_web_information",
      "description": "Search the web for current health information, medical guidelines, or healthcare news using the Integration Service Tavily search.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "tavily_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "search",
            "description": "Action to execute"
          },
          "query": {
            "type": "string",
            "description": "Search query for health information"
          },
          "include_domains": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Trusted health domains to include in search"
          },
          "max_results": {
            "type": "integer",
            "default": 5,
            "description": "Maximum number of search results"
          }
        },
        "required": ["query"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },
  {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Saving contact information..."
      },
      {
        "type": "request-complete",
        "content": "Contact information saved successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "save_contact_data",
      "description": "Save patient contact information and interaction history using the Integration Service HubSpot CRM integration.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "hubspot_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "create_contact",
            "description": "Action to execute"
          },
          "first_name": {
            "type": "string",
            "description": "Patient's first name"
          },
          "last_name": {
            "type": "string",
            "description": "Patient's last name"
          },
          "email": {
            "type": "string",
            "description": "Patient's email address"
          },
          "phone": {
            "type": "string",
            "description": "Patient's phone number"
          },
          "healthcare_needs": {
            "type": "string",
            "description": "Description of healthcare needs discussed"
          },
          "location": {
            "type": "string",
            "description": "Patient's location or area"
          },
          "interaction_notes": {
            "type": "string",
            "description": "Notes from the conversation"
          }
        },
        "required": ["first_name", "email", "healthcare_needs"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },
  {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Scheduling appointment..."
      },
      {
        "type": "request-complete",
        "content": "Appointment scheduled successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "schedule_calendar_appointment",
      "description": "Schedule healthcare appointments using the Integration Service Calendly integration.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "calendly_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "create_event",
            "description": "Action to execute"
          },
          "patient_name": {
            "type": "string",
            "description": "Patient's full name"
          },
          "patient_email": {
            "type": "string",
            "description": "Patient's email address"
          },
          "patient_phone": {
            "type": "string",
            "description": "Patient's phone number"
          },
          "appointment_type": {
            "type": "string",
            "description": "Type of appointment (consultation, follow-up, etc.)"
          },
          "preferred_date": {
            "type": "string",
            "description": "Preferred appointment date"
          },
          "preferred_time": {
            "type": "string",
            "description": "Preferred appointment time"
          },
          "provider_name": {
            "type": "string",
            "description": "Healthcare provider name"
          },
          "notes": {
            "type": "string",
            "description": "Additional notes or requirements"
          }
        },
        "required": ["patient_name", "patient_email", "appointment_type"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },
  {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Creating support ticket..."
      },
      {
        "type": "request-complete",
        "content": "Support ticket created successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "escalate_to_support",
      "description": "Create a support ticket for complex healthcare queries that cannot be resolved through standard provider search.",
      "parameters": {
        "type": "object",
        "properties": {
          "customer_name": {
            "type": "string",
            "description": "Patient's full name"
          },
          "customer_email": {
            "type": "string",
            "description": "Patient's email for follow-up"
          },
          "customer_phone": {
            "type": "string",
            "description": "Patient's phone number"
          },
          "search_query": {
            "type": "string",
            "description": "What the patient was searching for"
          },
          "location_searched": {
            "type": "string",
            "description": "Area or location they searched in"
          },
          "issue_description": {
            "type": "string",
            "description": "Detailed description of the issue or complex request"
          },
          "urgency_level": {
            "type": "string",
            "enum": ["low", "medium", "high", "urgent"],
            "default": "medium",
            "description": "Urgency level of the request"
          }
        },
        "required": ["customer_name", "customer_email", "search_query", "issue_description"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/premier-health/vapi-webhook`,
      "method": "POST"
    }
  }
];

return { tools, toolCount: tools.length };

const serverUrl = $('Setup Form').item.json.serverUrl;
const testEmail = $('Setup Form').item.json.testEmail;
const orgName = $('Setup Form').item.json.organizationName;

// Create comprehensive integration test scenarios
const integrationTests = [
  {
    "name": "HubSpot Contact Creation Test",
    "integration": "hubspot_consolidated",
    "action": "create_contact",
    "endpoint": `${serverUrl}/integration-webhooks/execute`,
    "payload": {
      "integration_name": "hubspot_consolidated",
      "action": "create_contact",
      "first_name": "Test",
      "last_name": "Patient",
      "email": testEmail,
      "phone": "+233201234567",
      "healthcare_needs": "Cardiology consultation in Accra",
      "location": "East Legon, Accra",
      "interaction_notes": "Voice assistant test - comprehensive integration workflow"
    }
  },
  {
    "name": "Resend Email Test",
    "integration": "resend_consolidated",
    "action": "send_email",
    "endpoint": `${serverUrl}/integration-webhooks/execute`,
    "payload": {
      "integration_name": "resend_consolidated",
      "action": "send_email",
      "recipient_email": testEmail,
      "subject": `${orgName} Healthcare Provider Information`,
      "content": "Dear Patient,\n\nThank you for using our voice assistant. Here are the healthcare providers we found:\n\n1. Korle-Bu Teaching Hospital - Cardiology Department\n2. Greater Accra Regional Hospital - General Medicine\n3. Trust Hospital - Specialist Care\n\nFor appointments, please call the providers directly or use our scheduling service.\n\nBest regards,\n${orgName} Team",
      "sender_name": orgName
    }
  },
  {
    "name": "Tavily Health Search Test", 
    "integration": "tavily_consolidated",
    "action": "search",
    "endpoint": `${serverUrl}/integration-webhooks/execute`,
    "payload": {
      "integration_name": "tavily_consolidated",
      "action": "search",
      "query": "cardiovascular health guidelines Ghana healthcare",
      "include_domains": ["who.int", "moh.gov.gh", "ghc.org.gh"],
      "max_results": 3
    }
  },
  {
    "name": "Calendly Appointment Test",
    "integration": "calendly_consolidated", 
    "action": "create_event",
    "endpoint": `${serverUrl}/integration-webhooks/execute`,
    "payload": {
      "integration_name": "calendly_consolidated",
      "action": "create_event",
      "patient_name": "Test Patient",
      "patient_email": testEmail,
      "patient_phone": "+233201234567",
      "appointment_type": "General Consultation",
      "preferred_date": "2024-01-15",
      "preferred_time": "10:00 AM",
      "provider_name": "Dr. Test Provider",
      "notes": "Voice assistant integration test appointment"
    }
  },
  {
    "name": "Premier Health Provider Search Test",
    "integration": "premier_health",
    "action": "search_providers",
    "endpoint": `${serverUrl}/premier-health/vapi-webhook`,
    "payload": {
      "query": "cardiologist",
      "location": "Accra",
      "specialty": "cardiology",
      "provider_type": "doctor",
      "max_results": 3
    }
  }
];

const testSummary = {
  "total_tests": integrationTests.length,
  "integrations_tested": [
    "hubspot_consolidated",
    "resend_consolidated", 
    "tavily_consolidated",
    "calendly_consolidated",
    "premier_health"
  ],
  "test_scenarios": integrationTests.map(test => ({
    "name": test.name,
    "integration": test.integration,
    "endpoint": test.endpoint
  })),
  "voice_test_instructions": {
    "step_1": "Call the generated phone number",
    "step_2": "Say: 'I need a cardiologist in Accra and want the information sent to my email'",
    "step_3": "Provide email when asked: " + testEmail,
    "step_4": "Ask to schedule an appointment",
    "step_5": "Ask to save your contact information",
    "step_6": "Request current health guidelines",
    "expected_results": [
      "HubSpot contact created",
      "Email sent with provider information",
      "Calendar appointment scheduled",
      "Web search results provided",
      "All integrations working via voice"
    ]
  }
};

return { integrationTests, testSummary };

const formData = $('Setup Form').item.json;
const assistant = $('Create Vapi Assistant').item.json;
const tools = $('Create Integration Service Tools').item.json;
const phoneNumber = $('Create Phone Number').item.json;
const tests = $('Test All Integrations').item.json;

const summary = {
  "workflow_name": "Premier Health Vapi Integration Service Workflow",
  "version": "002",
  "setup_date": new Date().toISOString(),
  "organization": {
    "name": formData.organizationName,
    "service_area": formData.serviceArea,
    "support_email": formData.supportEmail,
    "server_url": formData.serverUrl
  },
  "vapi_configuration": {
    "assistant_id": assistant.id,
    "assistant_name": assistant.name,
    "phone_number": phoneNumber.number || "Phone number creation pending",
    "phone_number_id": phoneNumber.id,
    "model": "claude-3-5-sonnet-20241022",
    "voice_provider": "11labs",
    "hipaa_enabled": true,
    "recording_enabled": true
  },
  "integration_architecture": {
    "service_type": "Integration Service Consolidated",
    "total_tools": tools.toolCount,
    "integration_endpoint": formData.serverUrl + "/integration-webhooks/execute",
    "premier_health_endpoint": formData.serverUrl + "/premier-health/vapi-webhook",
    "consolidated_services": [
      "hubspot_consolidated - CRM and contact management",
      "resend_consolidated - Email notifications", 
      "tavily_consolidated - Web search and research",
      "calendly_consolidated - Appointment scheduling",
      "premier_health - Healthcare provider search"
    ]
  },
  "tools_configured": [
    {
      "name": "search_healthcare_providers",
      "description": "Find doctors, hospitals, clinics, pharmacies",
      "endpoint": "premier-health/vapi-webhook"
    },
    {
      "name": "send_email_notification", 
      "description": "Send provider info via email (Resend)",
      "integration": "resend_consolidated"
    },
    {
      "name": "search_web_information",
      "description": "Search health information (Tavily)",
      "integration": "tavily_consolidated"
    },
    {
      "name": "save_contact_data",
      "description": "Save patient info (HubSpot)",
      "integration": "hubspot_consolidated"
    },
    {
      "name": "schedule_calendar_appointment",
      "description": "Schedule appointments (Calendly)",
      "integration": "calendly_consolidated"
    },
    {
      "name": "escalate_to_support",
      "description": "Create support tickets (Freshdesk)",
      "endpoint": "premier-health/vapi-webhook"
    }
  ],
  "testing_information": {
    "comprehensive_tests_configured": tests.testSummary.total_tests,
    "integrations_tested": tests.testSummary.integrations_tested,
    "test_email": formData.testEmail,
    "voice_test_instructions": tests.testSummary.voice_test_instructions
  },
  "key_improvements": [
    "Uses existing Integration Service architecture",
    "Leverages consolidated service instances", 
    "Proper webhook routing via integration-webhooks/execute",
    "Maintains Premier Health custom tools for healthcare search",
    "Comprehensive integration testing included",
    "All major CRM, Email, Search, Calendar tools integrated"
  ],
  "next_steps": [
    "Test voice conversation using provided phone number",
    "Verify all integrations work via voice commands",
    "Monitor integration webhook logs",
    "Check HubSpot for contact creation",
    "Verify emails sent to " + formData.testEmail,
    "Confirm calendar appointments in Calendly",
    "Review Tavily search results"
  ],
  "webhook_endpoints": {
    "main_webhook": formData.serverUrl + "/vapi-webhook",
    "integration_service": formData.serverUrl + "/integration-webhooks/execute",
    "premier_health": formData.serverUrl + "/premier-health/vapi-webhook"
  }
};

return summary;
